import { DataWidget } from './DataWidget.js';
import { COLORS } from './WorkspaceStore.js';
import { icon } from './icons.js';
export class ProjectsWidget extends DataWidget {
  constructor(config,dashboard){super({...config,title:'Проекты в движении'},dashboard);this.editing=false;}
  update(){const top=this.element('div','widget-subheading');top.append(this.element('span','subtle-text',`${this.store.data.projects.length} проектов · каждый шаг имеет значение`),this.actionButton(this.editing?'Скрыть':'＋ Проект','edit'));const list=this.element('div','project-list');for(const project of this.store.data.projects){const progress=this.store.progress(project.id);const row=this.element('div','project-row');const badge=this.element('span','project-icon');badge.style.background=`${COLORS[project.color]}55`;badge.append(icon('projects'));const details=this.element('div','project-details');details.append(this.element('strong','',project.name),this.element('small','',project.description||project.category));const track=this.element('div','project-progress');const bar=this.element('div','progress-track');const fill=this.element('i');fill.style.width=`${progress.percent}%`;fill.style.background=COLORS[project.color];bar.append(fill);track.append(this.element('small','',`${progress.done} / ${progress.total} задач`),bar);const percentage=this.element('div','progress-ring',`${progress.percent}%`);percentage.style.setProperty('--value',`${progress.percent}%`);percentage.style.setProperty('--color',COLORS[project.color]);row.append(badge,details,track,percentage);list.append(row);}if(!this.store.data.projects.length)list.append(this.empty('Собери большой замысел из маленьких шагов.'));this.content.replaceChildren(top,list);if(this.editing){const form=this.element('form','inline-form project-form');const name=this.input('name','Название проекта');name.maxLength=80;name.required=true;const description=this.input('description','Короткое описание');description.maxLength=240;const due=this.input('due','Дедлайн','date');due.required=true;form.append(name,description,due,this.select('category','Категория',[['Творчество','Творчество'],['Развитие','Развитие'],['Личное','Личное']]),this.submitButton('Создать проект'));this.content.append(form);}else{const link=this.element('a','text-link','Открыть доску проектов');link.href='#projects';this.content.append(link);} }
  action(action){if(action==='edit'){this.editing=!this.editing;this.update();if(this.editing)this.content.querySelector('[name=name]').focus();}}
  submit(form,values){this.store.addProject(Object.fromEntries(values));this.editing=false;this.update();this.dashboard.announce('Проект создан');}
}
